-- Form B, shorter, 19 Nov 2026 (the user's call).
-- A client who already has a website (Form B) is no longer asked:
--  - the Impressum details (legal name, legal form, address, VAT ID, register entry, responsible
--    person): they are taken from the current Impressum when the site is read. Form B only asks
--    "Are your legal notice and privacy policy up to date?" (legal_current, unchanged);
--  - the inboxes screen (email addresses on the site, where messages go, who approves);
--  - the logo, photos and files screen: the photos, logo and documents are copied from the
--    current website. Its Form B notice (files_from_site) is switched off.
-- "Is there anything that should sit behind a password?" moves from the business screen to the
-- page structure screen, in both forms. A screen left with no question is skipped, so Form B has
-- six screens: project, design, pages, integrations, access and legal, timing.
-- Form A (no website) asks exactly what it asked before.
--
-- Deploy the code first: older code shows a screen even when it has no question.
-- Rewrites every question from the seed (the live form matched it on 19 Nov). Safe to run more than once.

insert into onb_fields (id, screen_id, sort, type, label_de, label_en, help_de, help_en, placeholder_de, placeholder_en, required, allow_dont_know, ai_check, options, config, show_when, active) values
  ('contact_name', 'project', 10, 'text', 'Wie heißen Sie?', 'What is your name?', null, null, 'Name', 'Name', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('contact_company', 'project', 20, 'text', 'Wie heißt Ihr Unternehmen?', 'What is your company called?', null, null, 'Ihr Firmenname', 'Your company name', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('contact_email', 'project', 30, 'email', 'Wie lautet Ihre E-Mail-Adresse?', 'What is your email address?', 'Hierhin schicken wir Ihren Speicherlink und am Ende Ihr fertiges Briefing.', 'We will send your save link here and your finished brief at the end.', 'name@ihrefirma.de', 'name@yourcompany.com', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('booked_package', 'project', 40, 'radio', 'Welches Paket haben Sie gebucht?', 'Which package did you book?', null, null, null, null, true, true, false, '[{"value":"silver","label_de":"Silver","label_en":"Silver"},{"value":"gold","label_de":"Gold","label_en":"Gold"},{"value":"platinum","label_de":"Platinum","label_en":"Platinum"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('booked_page_band', 'project', 50, 'radio', 'Wie viele Seiten umfasst Ihr Angebot?', 'How many pages does your quote cover?', 'Das steht in Ihrem Angebot, als die Konfiguration, die Sie bestätigt haben.', 'It is on your quote, as the configuration you confirmed.', null, null, true, true, false, '[{"value":"14","label_de":"1 bis 4 Seiten","label_en":"1 to 4 pages","min":1,"max":4},{"value":"58","label_de":"5 bis 8 Seiten","label_en":"5 to 8 pages","min":5,"max":8},{"value":"912","label_de":"9 bis 12 Seiten","label_en":"9 to 12 pages","min":9,"max":12},{"value":"12p","label_de":"Mehr als 12 Seiten","label_en":"More than 12 pages","min":13,"max":null}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('project_type', 'project', 60, 'radio', 'Haben Sie schon eine Website?', 'Do you already have a website?', 'Davon hängt ab, welche Fragen wir Ihnen stellen. Mit einer Website lesen wir vieles direkt von dort.', 'This decides which questions we ask. If you have a website, we take a lot straight from it.', null, null, true, false, false, '[{"value":"new","label_de":"Nein, ich habe noch keine Website","label_en":"No, I don''t have a website yet"},{"value":"redesign","label_de":"Ja, und ich möchte eine neue","label_en":"Yes, and I want a new one"},{"value":"changes","label_de":"Änderungen an meiner bestehenden Seite","label_en":"Changes to my existing site","retired":true}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('existing_url', 'project', 70, 'url', 'Wie lautet Ihre aktuelle Website-Adresse?', 'What is your current website address?', null, null, 'https://www.ihrefirma.de', 'https://www.yourcompany.com', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["changes","redesign"]}]'::jsonb, true),
  ('redesign_reasons', 'project', 80, 'checkboxes', 'Warum möchten Sie eine neue Website?', 'Why do you want a new website?', 'Kreuzen Sie alles an, was passt.', 'Tick everything that applies.', null, null, true, false, false, '[{"value":"outdated","label_de":"Sie wirkt veraltet","label_en":"It looks outdated"},{"value":"enquiries","label_de":"Sie bringt zu wenige Anfragen","label_en":"It brings too few enquiries"},{"value":"phones","label_de":"Sie funktioniert auf dem Handy nicht gut","label_en":"It doesn''t work well on phones"},{"value":"updating","label_de":"Ich kann sie selbst kaum ändern","label_en":"I can hardly update it myself"},{"value":"slow","label_de":"Sie ist langsam","label_en":"It is slow"},{"value":"changed","label_de":"Mein Angebot hat sich verändert","label_en":"My business has changed"},{"value":"other","label_de":"Etwas anderes","label_en":"Something else"}]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"]}]'::jsonb, true),
  ('current_site_notes', 'project', 90, 'textarea', 'Was gefällt Ihnen an Ihrer jetzigen Website, und was soll anders werden?', 'What do you like about your current website, and what should change?', 'Ein paar Stichworte reichen.', 'A few words are enough.', 'Die Fotos mögen wir, aber man findet die Preise nicht', 'We like the photos, but people cannot find the prices', false, false, false, '[]'::jsonb, '{"rows":3,"max_chars":1000}'::jsonb, '[{"key":"project_type","values":["redesign"]}]'::jsonb, true),
  ('legal_name', 'business', 100, 'text', 'Wie lautet Ihr vollständiger Firmenname?', 'What is your full legal company name?', 'Genau so, wie er im Registereintrag oder auf Ihren Rechnungen steht, nicht so, wie er auf Ihrer aktuellen Website steht.', 'Exactly as it appears on your register entry or your invoices, not as it appears on your current website.', 'Ihr Firmenname', 'Your company name', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('legal_form', 'business', 110, 'text', 'Welche Rechtsform hat Ihr Unternehmen?', 'What is your legal form?', null, null, 'GmbH', 'GmbH, UG, sole trader…', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('address_street', 'business', 120, 'text', 'Wie lautet Ihre Straße und Hausnummer?', 'What is your street and number?', null, null, 'Straße und Hausnummer', 'Street and number', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('address_city', 'business', 130, 'text', 'Wie lauten Postleitzahl und Ort?', 'What is your postcode and city?', null, null, 'PLZ und Ort', 'Postcode and town', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('vat_id', 'business', 140, 'text', 'Wie lautet Ihre USt-IdNr.?', 'What is your VAT ID?', null, null, 'DE123456789', 'DE123456789', false, false, false, '[]'::jsonb, '{"tooltip_de":"Die USt-IdNr. steht in Ihrem Impressum, wenn Sie eine haben. In Deutschland ist diese Angabe gesetzlich vorgeschrieben.","tooltip_en":"Your VAT ID goes on your legal notice if you have one. In Germany that is a legal requirement."}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('register_entry', 'business', 150, 'text', 'Wie lauten Registergericht und Registernummer?', 'What is your register court and number?', 'Bitte frei lassen, wenn Sie keine haben.', 'Please leave it blank if you do not have one.', 'Amtsgericht Musterstadt, HRB 12345', 'Local court and number, e.g. HRB 12345', false, false, false, '[]'::jsonb, '{"tooltip_de":"Registergericht und Registernummer gehören ins Impressum. Außer bei einem Einzelunternehmen haben Sie das fast sicher.","tooltip_en":"The register court and number belong on your legal notice. Unless you are a sole trader, you will almost certainly have one."}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('content_responsible', 'business', 160, 'text', 'Wer ist für den Inhalt Ihrer Website verantwortlich?', 'Who is responsible for the content on your website?', 'Die benannte Person nach § 18 Abs. 2 MStV, meist die Inhaberin oder der Geschäftsführer.', 'The named person under § 18 Abs. 2 MStV, usually the owner or managing director.', 'Name', 'Name', true, false, false, '[]'::jsonb, '{"locales":["de"],"tooltip_de":"Nach § 18 Abs. 2 MStV muss im Impressum stehen, wer für die Inhalte verantwortlich ist. Das ist eine deutsche Vorgabe."}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('public_phone', 'business', 170, 'tel', 'Welche Telefonnummer sollen wir auf der Seite zeigen?', 'What phone number should we show on the site?', null, null, '+49 …', '+49 …', false, false, false, '[]'::jsonb, '{"tooltip_de":"Diese Nummer steht öffentlich auf Ihrer Website. Bitte geben Sie Ihre Mobilnummer nur an, wenn Sie sie dort zeigen wollen.","tooltip_en":"This number is published on your website. Only give us a mobile number if you want it shown there."}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('opening_hours', 'business', 180, 'textarea', 'Wie sind Ihre Öffnungszeiten?', 'What are your opening hours?', 'Tag für Tag, inklusive Abend- oder Wochenenddienst.', 'Day by day, including any evening or weekend cover.', 'Mo bis Fr, 8 bis 17 Uhr
