  ('regions_served', 'business', 200, 'textarea', 'Welche Regionen bedienen Sie?', 'Which regions do you serve?', 'Bitte genau, denn das steht später in Überschriften, Menüs, der Fußzeile und in dem Text, den Google anzeigt.', 'Please be precise, because this appears in headings, menus, footers and the text Google shows.', 'Ihre Stadt und 50 km drumherum, inklusive der Nachbarorte', 'Your town and 50km around it, including the neighbouring places', true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true},{"key":"service_scope","values":["one_town","several"]}]'::jsonb, true),
  ('second_address_details', 'business', 210, 'textarea', 'Besuchen Kunden noch weitere Adressen?', 'Do customers visit any other addresses?', 'Bitte frei lassen, wenn es nur eine gibt.', 'Please leave it blank if there is only one.', 'Werkstatt, zweite Adresse. Nur Abholung, kein Ausstellungsraum.', 'Workshop, second address. Collections only, no showroom.', false, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
