  ('routing_split', 'inboxes', 230, 'radio', 'Sollen verschiedene Arten von Nachrichten an verschiedene Personen gehen?', 'Should different types of message go to different people?', null, null, null, null, true, false, false, '[{"value":"yes","label_de":"Ja, bitte getrennt verteilen","label_en":"Yes, please route them separately"},{"value":"no","label_de":"Nein, bitte alles an eine Adresse","label_en":"No, please send everything to one address"}]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('routing_single', 'inboxes', 240, 'email', 'An welche Adresse soll alles gehen?', 'Which address should everything go to?', null, null, 'info@ihrefirma.de', 'info@yourcompany.com', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true},{"key":"routing_split","values":["no"]}]'::jsonb, true),
  ('notification_routing', 'inboxes', 250, 'repeater', 'Wohin soll welche Art von Nachricht gehen?', 'Where should each type of message go?', 'Bitte eine Zeile pro Art von Nachricht, mit der Adresse, an die sie gehen soll.', 'One row per type of message, with the address it should go to.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":8,"initial_rows":2,"add_label_de":"Weitere hinzufügen","add_label_en":"Add another","fields":[{"key":"type","type":"text","label_de":"Art der Nachricht","label_en":"Type of message","required":true,"placeholder_de":"Allgemeine Anfrage","placeholder_en":"General enquiry"},{"key":"address","type":"email","label_de":"Geht an","label_en":"Send it to","required":true,"placeholder_de":"info@ihrefirma.de","placeholder_en":"info@yourcompany.com"}]}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true},{"key":"routing_split","values":["yes"]}]'::jsonb, true),
  ('approver', 'inboxes', 260, 'text', 'Wer gibt die Website final frei?', 'Who gives final approval on the website?', 'Bitte ein Name: die Person, deren Ja bedeutet, dass wir live gehen können.', 'One name, please: the person whose yes means we can go live.', 'Name', 'Name', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('content_sender', 'inboxes', 270, 'text', 'Wer schickt uns Ihre Texte und Fotos?', 'Who will send us your text and photos?', null, null, 'Name', 'Name', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('brand_keep', 'design', 280, 'radio', 'Sollen Ihr Logo und Ihre Farben bleiben?', 'Should your logo and colours stay?', 'Wir übernehmen sie dann von Ihrer jetzigen Website und machen den Rest neu.', 'If so, we take them from your current website and make everything else new.', null, null, true, false, false, '[{"value":"keep","label_de":"Ja, Logo und Farben bleiben","label_en":"Yes, keep the logo and colours"},{"value":"fresh","label_de":"Nein, ich möchte einen ganz neuen Auftritt","label_en":"No, I want a completely new look"}]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["redesign"]}]'::jsonb, true),
  ('address_form', 'design', 290, 'radio', 'Wie sollen wir Ihre Besucher ansprechen?', 'How should the site address visitors?', 'So sprechen alle Texte Ihrer Website die Besucher an.', 'Every text on your website will address visitors this way.', null, null, true, false, false, '[{"value":"sie","label_de":"Mit „Sie“","label_en":"Formally (\"Sie\")"},{"value":"du","label_de":"Mit „du“","label_en":"Informally (\"du\")"}]'::jsonb, '{"locales":["de"]}'::jsonb, '[]'::jsonb, true),
  ('design_part_business', 'design', 300, 'notice', 'Ihr Unternehmen in Ihren Worten', 'Your business, in your words', 'Daraus entstehen die Texte Ihrer Website.', 'This becomes the basis for the words on your website.', null, null, false, false, false, '[]'::jsonb, '{"tone":"heading"}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('business_one_liner', 'design', 310, 'textarea', 'Was machen Sie, in einem Satz?', 'In one sentence, what do you do?', 'Bitte in den Worten, die Sie einem Kunden sagen würden, der vor Ihnen steht.', 'Please use the words you would say to a customer standing in front of you.', 'Wir sanieren Bäder, schnell und sauber, und wir werden an dem Tag fertig, den wir zugesagt haben.', 'We renovate bathrooms, quickly and cleanly and we finish on the day we said we would.', true, false, true, '[]'::jsonb, '{"rows":3,"min_chars":25,"ai_assist":true}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('target_audience', 'design', 320, 'textarea', 'Für wen ist Ihre Website vor allem da?', 'Who is your website mainly for?', 'Bitte beschreiben Sie die Person, nicht den Markt.', 'Please describe the person rather than the market.', 'Hauseigentümer über 50, die eine große Renovierung planen, meist ihre letzte.', 'Homeowners over 50 planning one big renovation, usually their last one.', true, false, true, '[]'::jsonb, '{"rows":3,"min_chars":25,"ai_assist":true}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('ideal_customer', 'design', 330, 'textarea', 'Wer ist Ihr idealer Kunde?', 'Who is your ideal customer?', 'Der Kunde, von dem Sie gern zehn mehr hätten: was er braucht und warum er gut zu Ihnen passt.', 'The customer you would happily have ten more of: what they need and why they suit you.', 'Paare, die ihr Haus gerade gekauft haben und das Bad einmal richtig machen wollen, statt es zu flicken.', 'Couples who have just bought their house and want the bathroom done properly once, rather than patched.', true, false, true, '[]'::jsonb, '{"rows":3,"min_chars":25,"ai_assist":true}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('excluded_audience', 'design', 340, 'textarea', 'Wen soll Ihre Website auf keinen Fall ansprechen?', 'Who should your website definitely not attract?', 'Optional. Zum Beispiel Anfragen, die Sie nicht annehmen, oder Kunden, die nicht zu Ihnen passen.', 'Optional. For example enquiries you do not take on, or customers who are not a good fit.', 'Schnäppchenjäger, die nur den günstigsten Preis vergleichen. Kleinreparaturen unter einer halben Stunde.', 'Bargain hunters who only compare the cheapest price. Small repairs under half an hour.', false, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('usps', 'design', 350, 'textarea', 'Warum wählen Kunden Sie und nicht Ihre Mitbewerber?', 'Why do customers choose you over your competitors?', 'Bitte konkret.', 'Please be concrete.', 'Festpreis, bevor wir anfangen. Dreißig Jahre in derselben Straße. Wir arbeiten nie mit Subunternehmern.', 'Fixed price agreed before we start. Thirty years in the same street. We never use subcontractors.', true, false, true, '[]'::jsonb, '{"rows":4,"min_chars":30,"ai_assist":true}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('competitors', 'design', 360, 'repeater', 'Wer sind Ihre wichtigsten Mitbewerber?', 'Who are your main competitors?', 'Einer reicht, zwei oder drei sind ideal. Bitte sagen Sie uns bei jedem, was Sie anders machen möchten.', 'One is enough, two or three is ideal. For each one, please tell us what you want to do differently.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":10,"initial_rows":1,"add_label_de":"Weiteren Mitbewerber hinzufügen","add_label_en":"Add another competitor","fields":[{"key":"url","type":"url","label_de":"Website des Mitbewerbers","label_en":"Competitor website","required":true,"placeholder_de":"https://www.mitbewerber.de","placeholder_en":"https://www.competitor.com"},{"key":"differently","type":"textarea","label_de":"Was möchten Sie anders machen?","label_en":"What would you do differently?","required":true,"min_chars":15,"placeholder_de":"Dort stehen keine Preise, wir wollen unsere auf jeder Leistungsseite klar zeigen","placeholder_en":"Their prices are hidden, we want ours clear on every service page"}]}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('tagline', 'design', 370, 'textarea', 'Haben Sie einen Slogan, der auf die Seite soll?', 'Do you have a slogan or tagline you want on your site?', null, null, 'Bäder, die halten.', 'Bathrooms built to last.', false, false, false, '[]'::jsonb, '{"rows":2,"ai_assist":true}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('proof_to_show', 'design', 380, 'checkboxes', 'Welche Belege sollen wir auf Ihrer Seite zeigen?', 'What proof would you like us to show on your site?', 'Bitte nur das, was Sie uns auch geben können, denn wir gestalten dafür Platz ein.', 'Please pick the ones you can actually give us, because we will design space for them.', null, null, true, false, false, '[{"value":"reviews","label_de":"Kundenbewertungen","label_en":"Customer reviews"},{"value":"years","label_de":"Jahre am Markt","label_en":"Years in business"},{"value":"certifications","label_de":"Zertifikate und Qualifikationen","label_en":"Certifications and qualifications"},{"value":"clients","label_de":"Kunden oder Partner mit Namen","label_en":"Named clients or partners"},{"value":"awards","label_de":"Auszeichnungen","label_en":"Awards"},{"value":"guarantees","label_de":"Garantien","label_en":"Guarantees"},{"value":"work_photos","label_de":"Fotos Ihrer Arbeit","label_en":"Photos of your work"},{"value":"before_after","label_de":"Vorher-nachher-Fotos","label_en":"Before and after photos"},{"value":"nothing","label_de":"Nichts davon, wir halten es lieber reduziert","label_en":"None of these, we prefer to keep it minimal"}]'::jsonb, '{"min_checked":1,"exclusive":["nothing"]}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('factual_claims', 'design', 390, 'textarea', 'Wie lauten die Angaben und wer hat sie bestätigt?', 'What are the details and who has confirmed them?', 'Bitte nennen Sie die Belege oder die Person, die sie für Ihre Website liefern kann.', 'Please provide the supporting details or the name of the person who can provide them for your website.', null, null, true, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true},{"key":"proof_to_show","values":["nothing"],"negate":true}]'::jsonb, true),
  ('design_part_feel', 'design', 400, 'notice', 'Wie sich Ihre Seite anfühlen soll', 'How your site should feel', 'Zwei Regler, jeweils mit Platz für Ihre eigenen Worte.', 'Two sliders, each with room for your own words.', null, null, false, false, false, '[]'::jsonb, '{"tone":"heading"}'::jsonb, '[]'::jsonb, true),
  ('tone_scale', 'design', 410, 'slider', 'Wie soll sich Ihre Seite anfühlen?', 'How should your site feel?', 'Bitte stellen Sie sich einen Ihrer Kunden vor, der die Seite öffnet, und wählen Sie, was sich für ihn richtig anfühlen würde.', 'Please picture one of your customers opening it and choose what would feel right to them.', null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"step":0.1,"captions":[{"de":"Verspielt und fröhlich","en":"Fun and playful"},{"de":"Warm und ungezwungen","en":"Warm and informal"},{"de":"Freundlich, aber professionell","en":"Friendly but professional"},{"de":"Professionell und zurückhaltend","en":"Professional and restrained"},{"de":"Formell und seriös","en":"Formal and serious"}],"examples":[{"de":"Kindergarten, Kreativwerkstatt, Trampolinpark","en":"Kindergarten, art and craft studio, trampoline park"},{"de":"Friseur, Café, Personal Trainer","en":"Hairdresser, café, personal trainer"},{"de":"Die meisten Handwerksbetriebe, die meisten Praxen","en":"Most trades, most clinics"},{"de":"Beratung, Arztpraxis","en":"Consultancy, medical practice"},{"de":"Kanzlei, Steuerberatung, Behörde","en":"Law firm, accountant, government"}]}'::jsonb, '[]'::jsonb, true),
  ('tone_note', 'design', 420, 'textarea', 'Was meinen Sie damit genau?', 'What exactly do you mean by that?', 'Optional. Zum Beispiel ein Gefühl, eine Marke oder eine Website, an die Sie dabei gedacht haben.', 'Optional. For example a feeling, a brand or a website you had in mind.', null, null, false, false, false, '[]'::jsonb, '{"rows":2}'::jsonb, '[]'::jsonb, true),
  ('personality_scale', 'design', 430, 'slider', 'Wie markant soll das Design sein?', 'How bold should the design be?', 'Hier geht es darum, wie stark das Design selbst auffällt, nicht darum, wie förmlich es ist.', 'This one is about how much the design itself stands out, not how formal it is.', null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"step":0.1,"captions":[{"de":"Klar und minimalistisch","en":"Clean and minimal"},{"de":"Zurückhaltend","en":"Understated"},{"de":"Ausgewogen","en":"Balanced"},{"de":"Eigenständig","en":"Distinctive"},{"de":"Markant","en":"Bold"}],"examples":[{"de":"Aufgeräumte Struktur, viel Weißraum","en":"Well-organised structure, generous white space"},{"de":"Ruhige Farben, klassische Schrift","en":"Calm colours, classic type"},{"de":"Ein paar Akzente, ohne laut zu werden","en":"A few accents without shouting"},{"de":"Eigene Fotos, charaktervolle Schrift","en":"Your own photography, characterful type"},{"de":"Große Gesten, starke Farben","en":"Big gestures, strong colours"}]}'::jsonb, '[]'::jsonb, true),
  ('personality_note', 'design', 440, 'textarea', 'Was meinen Sie damit genau?', 'What exactly do you mean by that?', 'Optional. Zum Beispiel ein Gefühl, eine Marke oder eine Website, an die Sie dabei gedacht haben.', 'Optional. For example a feeling, a brand or a website you had in mind.', null, null, false, false, false, '[]'::jsonb, '{"rows":2}'::jsonb, '[]'::jsonb, true),
  ('design_part_examples', 'design', 450, 'notice', 'Ihre Gestaltungsbeispiele', 'Your design examples', 'Zeigen Sie uns, was Ihnen gefällt. Wir gestalten 2 Entwürfe für Sie, jeder orientiert sich an einem Ihrer Favoriten. Ihre Inhalte und Ihr Logo haben dabei immer Vorrang.', 'Show us what you like. We design 2 proposals for you, each based on one of your favourites. Your own content and logo always come first.', null, null, false, false, false, '[]'::jsonb, '{"tone":"heading"}'::jsonb, '[]'::jsonb, true),
  ('example_sources', 'design', 460, 'checkboxes', 'Wie möchten Sie uns zeigen, was Ihnen gefällt?', 'How would you like to show us what you like?', 'Sie können auch beides wählen.', 'You can choose both.', null, null, true, false, false, '[{"value":"own","label_de":"Ich habe Websites, die mir gefallen","label_en":"I have websites I like","hint_de":"Sie fügen die Links ein und sagen uns, was Ihnen an jeder gefällt.","hint_en":"Add the links and tell us what you like about each one."},{"value":"gallery","label_de":"Zeigen Sie mir Beispiele","label_en":"Show me examples","hint_de":"Sie wählen aus Websites, die wir für Sie ausgesucht haben.","hint_en":"Choose from websites we have picked out for you."}]'::jsonb, '{"display":"tiles","min_checked":1}'::jsonb, '[]'::jsonb, true),
  ('references', 'design', 470, 'repeater', 'Websites, die Ihnen gefallen', 'Websites you like', 'So viele, wie Sie möchten. Kreuzen Sie bei jeder an, was Ihnen daran gefällt.', 'As many as you like. For each one, tick what you like about it.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":5,"initial_rows":1,"add_label_de":"Weitere Website hinzufügen","add_label_en":"Add another website","fields":[{"key":"url","type":"url","label_de":"Link","label_en":"Link","required":true,"max_chars":300,"placeholder_de":"https://www.beispielseite.de","placeholder_en":"https://www.example-site.com"},{"key":"liked","type":"ticks","label_de":"Was gefällt Ihnen daran?","label_en":"What do you like about it?","required":true,"max_chars":60,"options":[{"value":"layout","label_de":"Aufbau","label_en":"Layout"},{"value":"colours","label_de":"Farben","label_en":"Colours"},{"value":"fonts","label_de":"Schrift","label_en":"Fonts"},{"value":"photos","label_de":"Bilder","label_en":"Photos"},{"value":"feel","label_de":"Gesamteindruck","label_en":"Overall feel"}]},{"key":"likes","type":"text","label_de":"Was genau?","label_en":"Anything in particular?","max_chars":300,"placeholder_de":"Wie die Leistungen aufgelistet sind, eine pro Karte mit Preis","placeholder_en":"The way the treatments are listed, one per card with the price"},{"key":"dislikes","type":"text","label_de":"Was gefällt Ihnen nicht?","label_en":"Anything you do not like?","max_chars":200,"placeholder_de":"Zu viel Blau","placeholder_en":"Too much blue"}]}'::jsonb, '[{"key":"example_sources","values":["own"]}]'::jsonb, true),
  ('reference_sites', 'design', 480, 'checkboxes', 'Beispiele aus unserer Galerie', 'Examples from our gallery', 'Wählen Sie so viele, wie Sie möchten. In der Galerie sehen Sie die ganzen Seiten auf Laptop und Handy.', 'Tick as many as you like. The gallery shows the whole pages on a laptop and a phone.', null, null, true, false, false, '[{"value":"atha-hot-yoga","label_de":"Atha Hot Yoga","label_en":"Atha Hot Yoga","url":"https://www.athahotyoga.com/","image":"/onboarding/reference-sites/atha-hot-yoga.jpg","hint_de":"Ruhig, luftig, elegante Serifenschrift","hint_en":"Calm and airy, elegant serif headings","group_de":"Gesundheit & Yoga","group_en":"Health & Yoga"},{"value":"biograph","label_de":"Biograph","label_en":"Biograph","url":"https://www.biograph.com/","image":"/onboarding/reference-sites/biograph.jpg","hint_de":"Dunkel und hochwertig, Architekturfotos","hint_en":"Dark and premium, architectural photography","group_de":"Gesundheit & Yoga","group_en":"Health & Yoga"},{"value":"pure-sports-medicine","label_de":"Pure Sports Medicine","label_en":"Pure Sports Medicine","url":"https://puresportsmed.com/","image":"/onboarding/reference-sites/pure-sports-medicine.jpg","hint_de":"Moderne Praxis, Buchung gleich vorne","hint_en":"Modern clinic, booking right up front","group_de":"Gesundheit & Yoga","group_en":"Health & Yoga"},{"value":"lanserhof","label_de":"Lanserhof","label_en":"Lanserhof","url":"https://lanserhof.com/en","image":"/onboarding/reference-sites/lanserhof.jpg","hint_de":"Stiller Luxus, Landschaftsfotos","hint_en":"Quiet luxury, landscape photography","group_de":"Gesundheit & Yoga","group_en":"Health & Yoga"},{"value":"neko-health","label_de":"Neko Health","label_en":"Neko Health","url":"https://www.nekohealth.com/gb/en","image":"/onboarding/reference-sites/neko-health.jpg","hint_de":"Klar und zukunftsweisend, große Schrift","hint_en":"Clean and futuristic, big statement type","group_de":"Gesundheit & Yoga","group_en":"Health & Yoga"},{"value":"conductlaw","label_de":"ConductLaw","label_en":"ConductLaw","url":"https://www.conductlaw.com/","image":"/onboarding/reference-sites/conductlaw.jpg","hint_de":"Klassisch und vertrauenswürdig, Navy und Grün","hint_en":"Classic and trustworthy, navy and green","group_de":"Minimalistisch & seriös","group_en":"Minimal & Corporate"},{"value":"cote-et-ciel","label_de":"Côte&Ciel","label_en":"Côte&Ciel","url":"https://www.coteetciel.com/","image":"/onboarding/reference-sites/cote-et-ciel.jpg","hint_de":"Puristisch, Schwarz-Weiß, produktorientiert","hint_en":"Sleek black and white, product-led","group_de":"Minimalistisch & seriös","group_en":"Minimal & Corporate"},{"value":"rivian","label_de":"Rivian","label_en":"Rivian","url":"https://rivian.com/","image":"/onboarding/reference-sites/rivian.jpg","hint_de":"Starke Scroll-Animationen, große Bilder","hint_en":"Bold scroll animations, big imagery","group_de":"Verspielt & animiert","group_en":"Fun & Animated"},{"value":"graza","label_de":"Graza","label_en":"Graza","url":"https://www.graza.co/","image":"/onboarding/reference-sites/graza.jpg","hint_de":"Verspielte Illustrationen, warme Farben","hint_en":"Playful illustrations, warm colours","group_de":"Verspielt & animiert","group_en":"Fun & Animated"},{"value":"25hours-hotels","label_de":"25hours Hotels","label_en":"25hours Hotels","url":"https://25hours-hotels.com/","image":"/onboarding/reference-sites/25hours-hotels.jpg","hint_de":"Schräger Collage-Stil, kräftige Farben","hint_en":"Quirky collage style, bold colours","group_de":"Verspielt & animiert","group_en":"Fun & Animated"},{"value":"devol","label_de":"deVOL Kitchens","label_en":"deVOL Kitchens","url":"https://www.devolkitchens.co.uk/","image":"/onboarding/reference-sites/devol.jpg","hint_de":"Warm und handwerklich, klassische Serifenschrift","hint_en":"Warm and crafted, classic serif","group_de":"Warm & einladend","group_en":"Warm & Friendly"}]'::jsonb, '{"display":"cards","min_checked":1}'::jsonb, '[{"key":"example_sources","valu