  ('reference_likes', 'design', 490, 'repeater', 'Was gefällt Ihnen an Ihren Beispielen?', 'What do you like about the examples you chose?', 'Kreuzen Sie bei jedem an, was Ihnen gefällt. So wissen wir, was wir woher nehmen.', 'For each one, tick what you like. That tells us what to take from where.', null, null, true, false, false, '[]'::jsonb, '{"rows_from":"reference_sites","max_rows":11,"fields":[{"key":"site","type":"select","label_de":"Website","label_en":"Website","required":true,"max_chars":40,"options":[{"value":"atha-hot-yoga","label_de":"Atha Hot Yoga","label_en":"Atha Hot Yoga"},{"value":"biograph","label_de":"Biograph","label_en":"Biograph"},{"value":"pure-sports-medicine","label_de":"Pure Sports Medicine","label_en":"Pure Sports Medicine"},{"value":"lanserhof","label_de":"Lanserhof","label_en":"Lanserhof"},{"value":"neko-health","label_de":"Neko Health","label_en":"Neko Health"},{"value":"conductlaw","label_de":"ConductLaw","label_en":"ConductLaw"},{"value":"cote-et-ciel","label_de":"Côte&Ciel","label_en":"Côte&Ciel"},{"value":"rivian","label_de":"Rivian","label_en":"Rivian"},{"value":"graza","label_de":"Graza","label_en":"Graza"},{"value":"25hours-hotels","label_de":"25hours Hotels","label_en":"25hours Hotels"},{"value":"devol","label_de":"deVOL Kitchens","label_en":"deVOL Kitchens"}]},{"key":"liked","type":"ticks","label_de":"Was gefällt Ihnen daran?","label_en":"What do you like about it?","required":true,"max_chars":60,"options":[{"value":"layout","label_de":"Aufbau","label_en":"Layout"},{"value":"colours","label_de":"Farben","label_en":"Colours"},{"value":"fonts","label_de":"Schrift","label_en":"Fonts"},{"value":"photos","label_de":"Bilder","label_en":"Photos"},{"value":"feel","label_de":"Gesamteindruck","label_en":"Overall feel"}]},{"key":"dislikes","type":"text","label_de":"Was gefällt Ihnen nicht?","label_en":"Anything you do not like?","max_chars":200,"placeholder_de":"Zu viel Blau","placeholder_en":"Too much blue"}]}'::jsonb, '[{"key":"example_sources","values":["gallery"]},{"key":"reference_sites","values":["__set"]}]'::jsonb, true),
  ('reference_screenshots', 'design', 500, 'upload', 'Haben Sie Bilder von Gestaltungen, die Ihnen gefallen?', 'Do you have pictures of designs you like?', 'Screenshots, Pinterest-Pins oder Fotos, zum Beispiel von einer Broschüre, einem Schaufenster oder einer Zeitschriftenseite. Alle Bilder zusammen zählen als ein Beispiel.', 'Screenshots, Pinterest pins or photos, for example of a brochure, a shop front or a magazine page. All your pictures together count as one example.', null, null, false, false, false, '[]'::jsonb, '{"max_files":10,"max_total_mb":25,"accept":["jpg","jpeg","png","webp","gif"]}'::jsonb, '[{"key":"example_sources","values":["__set"]}]'::jsonb, true),
