  ('design_part_look', 'design', 520, 'notice', 'Farben, Schrift und Bilder', 'Colours, lettering and pictures', 'Die Details, die für beide Entwürfe gelten.', 'The details that apply to both proposals.', null, null, false, false, false, '[]'::jsonb, '{"tone":"heading"}'::jsonb, '[]'::jsonb, true),
  ('brand_guidelines', 'design', 530, 'radio', 'Haben Sie ein Marken- oder Gestaltungshandbuch?', 'Do you have a brand or design guideline document?', 'Wenn ja, ersparen Sie uns das Raten, und wir halten uns daran.', 'If you have one it saves us guessing and we will follow it.', null, null, true, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[{"key":"brand_keep","values":["keep"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('brand_guidelines_link', 'design', 540, 'url', 'Link oder Datei', 'Link or file', null, null, 'https://drive.google.com/…', 'https://drive.google.com/…', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"brand_guidelines","values":["yes"]},{"key":"brand_keep","values":["keep"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('brand_colours', 'design', 550, 'text', 'Welche Farben hat Ihre Marke?', 'What are your brand colours?', 'Hex-Codes, wenn Sie sie haben, sonst bitte beschreiben.', 'Hex codes if you have them, otherwise please describe them.', 'Das Dunkelblau von unseren Transportern und ein warmes Orange. #1E5EFF, #F27127', 'The dark blue from our vans and a warm orange. #1E5EFF, #F27127', false, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"brand_guidelines","values":["yes"],"negate":true},{"key":"brand_keep","values":["keep"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('colour_mood', 'design', 560, 'checkboxes', 'Welche Farbstimmung passt zu Ihrem Unternehmen?', 'What colour mood fits your business?', 'Bitte wählen Sie, wie die Farben wirken sollen. Höchstens zwei.', 'Please choose how the colours should feel in use. Up to two.', null, null, true, false, false, '[{"value":"light","label_de":"Hell und luftig","label_en":"Light and airy"},{"value":"dark","label_de":"Dunkel und hochwertig","label_en":"Dark and premium"},{"value":"warm","label_de":"Warm und erdig","label_en":"Warm and earthy"},{"value":"cool","label_de":"Kühl und klar","label_en":"Cool and crisp"},{"value":"bold","label_de":"Kräftig und kontrastreich","label_en":"Bold and high contrast"},{"value":"muted","label_de":"Dezent und ruhig","label_en":"Soft and calm"}]'::jsonb, '{"min_checked":1,"max_checked":2}'::jsonb, '[{"key":"brand_keep","values":["keep"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('typography_feel', 'design', 570, 'radio', 'Welche Art von Schrift fühlt sich richtig an?', 'Which kind of lettering feels right?', 'Nicht die genaue Schriftart, nur die Familie, zu der sie gehört.', 'Not the exact font, please, just the family it belongs to.', null, null, true, true, false, '[{"value":"classic","label_de":"Klassisch und traditionell","label_en":"Classic and traditional"},{"value":"modern","label_de":"Klar und modern","label_en":"Clean and modern"},{"value":"technical","label_de":"Technisch und präzise","label_en":"Technical and precise"},{"value":"warm","label_de":"Warm und rund","label_en":"Warm and rounded"},{"value":"trust","label_de":"Entscheiden Sie, wir vertrauen Ihnen","label_en":"You choose, we trust you"}]'::jsonb, '{}'::jsonb, '[{"key":"brand_keep","values":["keep"],"negate":true,"ifMissing":true}]'::jsonb, true),
  ('photo_subjects', 'design', 580, 'checkboxes', 'Welche Fotos wollen Sie auf Ihrer Seite?', 'What photos do you want on your site?', 'Wir gleichen das mit den Dateien ab, die Sie uns später schicken.', 'We will check this against the files you send us later.', null, null, true, false, false, '[{"value":"work","label_de":"Unsere fertigen Arbeiten","label_en":"Our finished work"},{"value":"team","label_de":"Uns und unser Team","label_en":"Us and our team"},{"value":"premises","label_de":"Unsere Räume","label_en":"Our premises"},{"value":"products","label_de":"Unsere Produkte","label_en":"Our products"},{"value":"customers","label_de":"Menschen wie unsere Kunden","label_en":"People like our customers"},{"value":"none","label_de":"Kaum Fotos, lieber Schrift und Grafik","label_en":"Few photos, led by type and graphics"}]'::jsonb, '{"min_checked":1,"exclusive":["none"]}'::jsonb, '[]'::jsonb, true),
  ('hero_intent', 'design', 590, 'radio', 'Was sollen Menschen zuerst sehen, bevor sie scrollen?', 'What should people see first, before they scroll?', null, null, null, null, true, false, false, '[{"value":"work_photo","label_de":"Ein Foto unserer Arbeit","label_en":"A photo of our work"},{"value":"team_photo","label_de":"Ein Foto von uns","label_en":"A photo of us"},{"value":"statement","label_de":"Einen klaren Satz, was wir tun","label_en":"A clear statement of what we do"},{"value":"price","label_de":"Einen Preis oder ein Angebot","label_en":"A price or an offer"},{"value":"form","label_de":"Ein Buchungs- oder Anfrageformular","label_en":"A booking or enquiry form"},{"value":"video","label_de":"Ein kurzes Video","label_en":"A short video"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('homepage_density', 'design', 600, 'radio', 'Wie viel soll Ihre Startseite sagen?', 'How much should your homepage say?', 'Es gibt kein Richtig, bitte entscheiden Sie danach, ob Ihre Kunden schnell entscheiden oder sich Zeit nehmen.', 'There is no right answer, so please choose by whether your customers decide quickly or take their time.', null, null, true, false, false, '[{"value":"short","label_de":"Kurz und knackig, sie sollen anrufen","label_en":"Short and punchy, we want them to call"},{"value":"balanced","label_de":"Ausgewogen, genug zum Entscheiden","label_en":"Balanced, enough to decide"},{"value":"detailed","label_de":"Ausführlich, unsere Kunden lesen alles, bevor sie kaufen","label_en":"Detailed, our customers read everything before they buy"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('avoid', 'design', 610, 'textarea', 'Gibt es etwas, das Sie auf Ihrer Website nicht wollen?', 'Is there anything you do not want on your website?', 'Bitte deutlich, denn wir behandeln das als harte Regel, nicht als Vorliebe.', 'Please be blunt, because we treat this as a hard rule rather than a preference.', 'Keine Stockfotos von Menschen im Anzug. Nichts, was nach Krankenhaus aussieht. Keine Slider.', 'No stock photos of people in suits. Nothing that looks like a hospital. No sliding banners.', true, false, false, '[]'::jsonb, '{"rows":3,"none_label_de":"Mir fällt nichts ein","none_label_en":"Nothing comes to mind"}'::jsonb, '[]'::jsonb, true),
  ('page_review', 'pages', 620, 'repeater', 'Welche Ihrer jetzigen Seiten sollen bleiben?', 'Which of your current pages should stay?', 'Diese Seiten haben wir im Menü Ihrer Website gefunden. Fehlt eine, fügen Sie sie unten hinzu.', 'We found these pages in the menu of your website. If one is missing, add it below.', null, null, true, false, false, '[]'::jsonb, '{"site_menu":"existing_url","min_rows":1,"max_rows":30,"initial_rows":0,"add_label_de":"Seite hinzufügen","add_label_en":"Add a page","fields":[{"key":"page","type":"text","label_de":"Seite","label_en":"Page","required":true,"max_chars":80,"placeholder_de":"Über uns","placeholder_en":"About us"},{"key":"decision","type":"select","label_de":"Was passiert damit?","label_en":"What happens to it?","required":true,"options":[{"value":"keep","label_de":"Bleibt","label_en":"Keep"},{"value":"change","label_de":"Bleibt, aber anders","label_en":"Keep, but change it"},{"value":"drop","label_de":"Fällt weg","label_en":"Drop"}]},{"key":"note","type":"text","label_de":"Was soll anders werden?","label_en":"What should change?","max_chars":200,"placeholder_de":"Kürzer, mit Preisen","placeholder_en":"Shorter, with prices"}]}'::jsonb, '[{"key":"project_type","values":["redesign"]}]'::jsonb, true),
