  ('photo_portal', 'files', 1010, 'textarea', 'Welches Portal und wer besorgt unseren Zugang?', 'Which portal and who arranges our access?', 'Bitte fangen Sie jetzt damit an, denn Lieferantenzugänge dauern meist ein bis zwei Wochen.', 'Please start this now, because supplier logins usually take a week or two to arrange.', 'Händlerportal Ihres Lieferanten. Wer kann den Zugang beantragen?', 'Your supplier''s dealer portal. Who can request access?', true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true},{"key":"photo_portal_needed","values":["yes"]}]'::jsonb, true),
