  ('content_ready_date', 'timing', 1180, 'date', 'Wann können Sie uns alle Texte und Fotos schicken?', 'When can you send us all your text and photos?', 'Dieses Datum, nicht der Starttermin, entscheidet darüber, wann wir fertig werden können.', 'This date, not the launch date, is what actually determines when we can finish.', null, null, true, false, false, '[]'::jsonb, '{"min_date":"today"}'::jsonb, '[{"key":"project_type","values":["redesign"],"negate":true,"ifMissing":true}]'::jsonb, true),
