-- The Form B notice "We take your photos and logo": its screen is gone from Form B.
update onb_fields set active = false where id = 'files_from_site';

-- The brief says where a Form B client's Impressum details come from. Only where it still reads as shipped.
update onb_brief_sections
set instructions = 'Legal-page decision (reuse / none / not sure) and who reviewed them; extra documents needed; whether the business sells to consumers online and the accessibility (BFSG) note if so; the Impressum data: legal name, form, address, register entry, VAT ID, responsible person and public phone. If the client has a website (legal_current is answered), the Impressum data was not asked: say it is taken from their current Impressum, and whether they said it is up to date, are not sure or need it updated. Accounts and domain: who holds which login, names only. The domain is only asked for a brand new site; for changes to an existing one it is the current website address.'
where id = 'legal'
  and replace(instructions, E'\r', '') = 'Legal-page decision (reuse / none / not sure) and who reviewed them; extra documents needed; whether the business sells to consumers online and the accessibility (BFSG) note if so; the Impressum data: legal name, form, address, register entry, VAT ID, responsible person and public phone. Accounts and domain: who holds which login, names only. The domain is only asked for a brand new site; for changes to an existing one it is the current website address.';
